#: bundled into every build and linked locally (below), so a submitted Peg is
#: self-contained and never depends on the network. The same file is published
#: to cdn.workpeg.com via CI (later); a build does not use the online copy.
_PEGMENT_CSS = Path(__file__).parent / "runtime" / "pegment.css"

#: The (fixed, non-configurable) href the build links — the bundled local copy.
